namespace OpenTPW;

/// <summary>
/// The guest walk's approximation register (docs/GUESTS.md, "Walking"; docs/reverse/WALK-plan.md §11, §13). Each entry is
/// tagged <c>[APPROX:WALK-NNN]</c> at its code site. The speed model is traced from the Mac binary; a guest's walk on the park's
/// cells is tp.exe's (GuestNavigation.Navigate: the route search 0x511420, the edge test 0x4d8750 and commit 0x510510, avoid_walls
/// 0x50e4a0 with its corner blocks, follow_path 0x50ed10 with the block stamps, the progress 0x50fd40 and the steering step 0x50f3b0
/// with its own arithmetic), checked against the original in the x86 oracle (docs/reverse/ORACLE.md X25); separation is the Mac's (BIN labels at the code sites).
/// Retired: WALK-002 (avoid_walls' corner blocks and the position's cell), WALK-004 (the whole-walk destinations of state 10, one route to the ride's back cell, and
/// state 18, one route to the gate's crossing cell), WALK-008 (the arrival chain, states 0 to 5, and the way home, over the cell map) and WALK-009 (the progress measure and its resets).
/// </summary>
public static class WalkApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("WALK-003", "separation's neighbours are the guests outside rides and shops (not Using, HeldByGuard or Gone) of a cell followed by the staff on it (classes 4-8, as the staff sweep does with the guests); the original's query (tp.exe 0x5102f0, Mac 0x10087c, at most five neighbours) visits each cell's things in the order they were head-inserted when they entered it (0x50b6a0 via 0x4d91f0), keeps class-1 guests whatever their state, and also keeps the online avatar (class 18); the neighbour position (thing +4/+6 = navigation position >> 8, written by 0x4fa2a0) matches OpenTPW's (the per-turn rebuilt cell lists themselves are [EXT:guest-cell-lists])"),
		("WALK-005", "the edge test 0x4d8750 reads only the cell map: OpenTPW's cells hold no object or thing references, so an object standing on a target cell (0x5363f0, its type record's 0x53ad20 bits) never blocks, a type-9 target's ride thing (on its owner cell +0x10, type 3: 0x42a440, 0x4dd4e0 +0x118) never decides a mask-2 step, and the underground link byte +0x22 (0x522770 with 0x81b4cc) is not kept; the types are the ones OpenTPW's map holds (map init 0x536490's 0, 1, 2, 7 and 0x1e, and the path, queue, entrance, exit, object and track cells its tools write)"),
		("WALK-006", "the last walk into the ride's entrance cell (state 13's walk to the stand point: the route request 0x4FA5F0 of 0x4FFFF0 to the entry cell +0x36, read by 0x4DEDF0) is the search and edge-test walk of every other walk, and an imported park's entrance and exit cells carry the link byte +0x0C of their saved records, as the load reads it (a placement lays the same byte, through the outside path cell's link writer reaching the type-9 cell along its queue link; Easymode's nine entrance and exit cells match); where a park resumed from an OpenTPW save made before the import took that byte holds an entrance cell with no link byte toward the path outside, the edge test 0x4d8750 refuses the step and the guest keeps OpenTPW's route walk into the cell, where the original dismisses a guest whose route to the stand point fails (\"the player has removed the path from under me\": the called slot is released 0x4E0AC0, the guest unlinked 0x4DDD20 and dismissed 0x5012F0); the route walk's own quirks stay for those walks (the route's cells, and the queue's next cells ahead and behind, are the walkable ones, avoid_walls has its edge branch only, refills come from the stored route, the stuck reroute prepends the current cell to the rest, progress compares raw remaining distances in the five-waypoint window, the Mac's rounding FixMul/FixDiv apply) -- evidence needed: none for the original; the old saves' cells wait for a repair by the placement's link writer"),
		("WALK-007", "the queue recompute's own stamp of its back cell (tp.exe 0x4de1f0: the counter raised by 0x4d8c50 and written into the back cell's block by 0x4d8c60) is made after the queue tool's edits, but not yet after a path laid over a queue end or a cell clear of a queue cell (0x5346d0, 0x5367a0 call 0x4de1f0 on the owning ride, found through the cell's owner word +0x10, which OpenTPW's cells do not keep); the block stamps of every cell type change (0x4d8c60 from 0x5346d0, 0x5348d0, 0x538fc0) and the walk's comparison (0x50ed6c, a search in mode 1) are ported"),
		("WALK-010", "thing ids are slots of one pool of 10239 for every kind of thing, taken in the order the park builds them as tp.exe's allocator does (0x516270: ids 1, 2, 3, ... on a fresh park, the world's ten singletons first, then the gates and lights as 11 and 12; a freed slot taken again last in, first out, after the turn's deferred destroy, 0x516310; an original save's chain kept slot by slot with the free list rebuilt ascending, 0x518D43), so the guest's needs phase, reseed, prank flag and the id rules read the original's numbers; but the pool holds only what OpenTPW builds, so a thing the original builds that OpenTPW does not (the End finale object of RIDES-019, the online persons and avatar, the developer prototype ride) takes no slot, and a saved thing of an imported original save that OpenTPW does not rebuild holds a placeholder slot that nothing simulates or frees, where the original's thing would run on and be destroyed in time; the attraction ids the guests' histories, queues and the economy hold are the script world's counter, not the objects' thing ids — evidence needed: what else the original builds over a session (the callers of the destroy request 0x50B780 and of the thing constructors outside the online code)")
	};
}
